type command struct{ op, target string; reply chan string }

cmds := make(chan command, 8)                     // the in-process control bus
mux := http.NewServeMux()                         // admin surface on its own listener
mux.HandleFunc("/admin/cmd", func(w http.ResponseWriter, r *http.Request) {
    c := command{op: r.URL.Query().Get("op"), target: r.URL.Query().Get("target"),
        reply: make(chan string, 1)}
    cmds <- c
    fmt.Fprintln(w, <-c.reply)
})
mux.Handle("/debug/pprof/", http.DefaultServeMux) // or blank-import net/http/pprof
go http.ListenAndServe("127.0.0.1:6060", mux)     // loopback or a dedicated interface
ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGTERM, syscall.SIGINT)
defer stop()

